const sheetsRows = $('Google Sheets: Leer Filas').all().map(i => i.json);
const dbCitas = $('DB: Citas Confirmadas Activas').all().map(i => i.json);

// GUARDA CRÍTICA ANTI-BORRADO: Si Sheets no respondió o devolvió error, abortar
if (!Array.isArray(sheetsRows) || sheetsRows.length === 0) {
  return [];
}
const primerElemento = sheetsRows[0];
if (primerElemento.error || primerElemento.errorMessage || !('ID Cita' in primerElemento)) {
  return [];
}

// Mapear filas de sheets por ID Cita
const sheetsMap = new Map();
for (const row of sheetsRows) {
  const rawId = (row['ID Cita'] || '').trim().toLowerCase();
  if (rawId) {
    sheetsMap.set(rawId, row);
  }
}

const citasParaCancelar = [];

for (const cita of dbCitas) {
  if (!cita.id) continue;
  const citaId = cita.id.toLowerCase();
  const sheetRow = sheetsMap.get(citaId);

  if (!sheetRow) {
    // Caso 1: La fila fue eliminada/borrada completamente de Google Sheets
    citasParaCancelar.push({
      json: {
        cita_id: cita.id,
        cliente: cita.cliente,
        servicio: cita.servicio,
        fecha_inicio: cita.fecha_inicio,
        fecha_inicio_bogota: cita.fecha_inicio_bogota,
        motivo_sync: 'Fila eliminada de Google Sheets'
      }
    });
  } else {
    const estadoSheet = (sheetRow['Estado'] || '').trim().toLowerCase();
    if (estadoSheet.startsWith('cancel')) {
      // Caso 2: La celda Estado fue cambiada a Cancelada
      citasParaCancelar.push({
        json: {
          cita_id: cita.id,
          cliente: cita.cliente,
          servicio: cita.servicio,
          fecha_inicio: cita.fecha_inicio,
          fecha_inicio_bogota: cita.fecha_inicio_bogota,
          motivo_sync: 'Marcada como Cancelada en Google Sheets'
        }
      });
    }
  }
}

return citasParaCancelar;

